import{b as t,I as a,g as o,j as r}from"./chunks/framework.CrSplIeq.js";const u=JSON.parse('{"title":"Proxy (Request Forwarding)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/api-proxy.md","filePath":"guide/api-proxy.md"}'),s={name:"guide/api-proxy.md"};function n(i,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="proxy-request-forwarding" tabindex="-1">Proxy (Request Forwarding) <a class="header-anchor" href="#proxy-request-forwarding" aria-label="Permalink to &quot;Proxy (Request Forwarding)&quot;">​</a></h1><p>Requests that match a registered route but are not handled by a <code>/gatelin/*</code> admin or session router are forwarded to the target microservice. Every request still goes through <code>checkRoute</code> first — including proxied ones.</p><p>Proxied traffic is rate-limited to <strong>200 requests per IP per minute</strong>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/users/123</span></span>
<span class="line"><span>Authorization: Bearer &lt;access_token&gt;</span></span></code></pre></div><p>With Traefik stripping the <code>/api</code> prefix, Gatelin sees <code>/users/123</code> (or whatever pattern you registered).</p><p><strong>Flow:</strong></p><ol><li>Gatelin validates the route exists and matches the configured pattern</li><li>Validates the JWT access token (if <code>protected: true</code> for the route)</li><li>Checks the consumer session and that a permission grants access</li><li>Checks ACL route, operation, scope, condition, and field permissions</li><li>Injects <code>x-consumer-user-id</code>, <code>x-consumer-name</code>, and optionally <code>x-acl-conditions</code> and <code>x-acl-fields</code></li><li>Streams the request to <code>{SERVER_SCHEME}{APP_NAME}-{serviceName}-{ENV_NAME}:{PORT}</code> with the original method, path, query string, body, and safe client headers</li><li>Streams the microservice status, headers, and body back to the client</li></ol><h2 id="transparent-forwarding" tabindex="-1">Transparent forwarding <a class="header-anchor" href="#transparent-forwarding" aria-label="Permalink to &quot;Transparent forwarding&quot;">​</a></h2><p>Proxy bodies are not parsed or re-serialized by Gatelin. JSON, form data, multipart uploads, binary payloads, and streaming responses pass through as bytes. Upstream response headers such as <code>Content-Type</code>, <code>Location</code>, and <code>Set-Cookie</code> are preserved.</p><p>Hop-by-hop headers are removed in both directions. The client <code>Authorization</code>, <code>Cookie</code>, and <code>X-CSRF-Token</code> request headers are also removed because they authenticate the client to Gatelin, not to an internal service. Protected services receive trusted identity and ACL context through the injected <code>x-consumer-*</code> and <code>x-acl-*</code> headers.</p><p>Because proxy bodies remain streams, Gatelin does not rewrite JSON fields or filters for proxied routes. Services must enforce the <code>x-acl-fields</code> and <code>x-acl-conditions</code> context they receive on reads, writes, history, and schema output. Gatelin&#39;s own <code>/gatelin/*</code> APIs continue to parse JSON and apply field and condition filtering internally. See <a href="./integration.html#enforcing-acl-headers-in-a-service">Integrating Gatelin — Enforcing ACL headers</a> for the required upstream contract.</p><h2 id="graphql-over-http" tabindex="-1">GraphQL over HTTP <a class="header-anchor" href="#graphql-over-http" aria-label="Permalink to &quot;GraphQL over HTTP&quot;">​</a></h2><p>Register <code>/graphql</code> (or any path your service uses) as a normal proxied route. Queries and mutations are ordinary <code>POST</code>/<code>GET</code> HTTP bodies and now pass through as bytes. Gatelin does not parse GraphQL documents or enforce field-level GraphQL ACL; services should honor <code>x-acl-*</code> if they need row or field rules.</p><p>GraphQL subscriptions are not JSON-over-HTTP. Use <a href="#server-sent-events">SSE</a> or <a href="#websockets">WebSocket</a> for those transports, with the same route + JWT + ACL handshake.</p><h2 id="server-sent-events" tabindex="-1">Server-Sent Events <a class="header-anchor" href="#server-sent-events" aria-label="Permalink to &quot;Server-Sent Events&quot;">​</a></h2><p>SSE is HTTP/1.1 (<code>GET</code>, <code>Accept: text/event-stream</code> or an upstream <code>Content-Type: text/event-stream</code>). The proxy streams chunks without buffering the full body.</p><p>The generic <code>UPSTREAM_TIMEOUT_MS</code> idle timeout is <strong>disabled</strong> for event streams so sparse heartbeats are not killed after 30s. Disconnect when the client or upstream closes the socket. <code>Last-Event-ID</code> is a normal request header and is forwarded.</p><p>Register the SSE path as a <code>GET</code> route. ACL is checked once on the GET; Gatelin does not inspect event payloads.</p><h2 id="websockets" tabindex="-1">WebSockets <a class="header-anchor" href="#websockets" aria-label="Permalink to &quot;WebSockets&quot;">​</a></h2><p>WebSocket <code>Upgrade</code> never enters Express. The HTTP server handles <code>upgrade</code> beside the REST pipeline:</p><ol><li>Match a registered <strong>GET</strong> route for the path</li><li>Enforce CORS origin whitelist when <code>Origin</code> is present</li><li>Authenticate and authorize once (JWT + ACL)</li><li>Inject <code>x-consumer-*</code> / <code>x-acl-*</code> on the handshake only</li><li>Pipe sockets after <code>101 Switching Protocols</code></li></ol><p>Browser <code>WebSocket</code> cannot set <code>Authorization</code>. Protected routes may pass the access token as <code>?access_token=</code> or <code>?token=</code>; Gatelin uses it for the handshake and <strong>strips it</strong> before contacting the upstream. Node and other clients may send <code>Authorization: Bearer</code>. Cookies and CSRF headers are not forwarded.</p><p>After <code>101</code>, frames are opaque. There is no per-message ACL.</p><p>Traefik must allow WebSockets on the route that strips <code>/api</code> and forwards to Gatelin (default in Traefik HTTP routers).</p><h2 id="grpc" tabindex="-1">gRPC <a class="header-anchor" href="#grpc" aria-label="Permalink to &quot;gRPC&quot;">​</a></h2><p>Native gRPC (HTTP/2, trailers, <code>application/grpc</code>) is <strong>out of scope</strong>. Terminate gRPC on Traefik or Envoy on a separate listener. grpc-web over HTTP/1.1 may pass as opaque bytes, but Gatelin does not implement HTTP/2 or gRPC status trailers.</p><h2 id="health-check" tabindex="-1">Health Check <a class="header-anchor" href="#health-check" aria-label="Permalink to &quot;Health Check&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /gatelin/health</span></span></code></pre></div><p>Returns liveness and database readiness. This endpoint bypasses <code>checkRoute</code>.</p>`,30)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
